WITH parent AS (
    SELECT id FROM skillup_dev.programmes
    WHERE lower(trim(discipline)) = 'social sciences'
      AND lower(trim(name)) = 'sociology'
    ORDER BY id
    LIMIT 1
)
DELETE FROM skillup_dev.programme_abilities
WHERE programme_id = (SELECT id FROM parent);

WITH parent AS (
    SELECT id FROM skillup_dev.programmes
